  "status": "SUPPORTED",
  "claim": {
    "component_id": "C004.component",
    "value": "Approval applicability must be established for each order; it cannot be assumed that all 14 flagged orders required approval.",
    "scope": "Order-specific applicability under the relevant threshold and approval requirements.",
    "provenance": {
      "refs": [
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans directly supply the applicability inquiry and the prohibition on assuming that all flagged orders required approval."
    }
  },
  "signal_basis": {
    "component_id": "C004.signal_basis",
    "value": "The orders are flagged for missing approval attachments. The prescribed inquiry checks each order's identity, value, placement date, applicable threshold and approval requirements rather than assuming that the flag establishes applicability.",
    "scope": "The 14 flagged orders and the order-specific applicability inquiry.",
    "provenance": {
      "refs": [
        {
          "source_id": "P001",
          "role": "SUPPORT"
        },
        {
          "source_id": "P003",
          "role": "SUPPORT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle identifies the attachment-based selection and the required checks governing applicability."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C004.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without a separate unresolved empirical relation."
    }
  },
  "rationale": "A missing attachment does not establish that an order falls within the approval rule. Applicability depends on the order's value and relevant requirements, so checking those conditions individually licenses this procedural claim. It does not assert that any particular order is exempt.",
  "uncertainty": "Actual applicability remains to be determined for each order; that uncertainty supports the inquiry and does not undermine its warrant.",
  "anomalies": []
}
